-- chair-step: inverse of read_lane_v2_b3_66_research_rs_source — un-enrolls research.rs_source from read-lane v2 and regenerates it back to the set-form read lane.
delete from iam.read_lane_v2_rollout where token = (select token from platform.entity_types where schema_name = 'research' and table_name = 'rs_source' and is_active);
select iam.apply_rls('research', 'rs_source', (select token from platform.entity_types where schema_name = 'research' and table_name = 'rs_source' and is_active), (select rls_variant from platform.entity_types where schema_name = 'research' and table_name = 'rs_source' and is_active));
